local HandTrowelMaker = {}
local PRODUCTS = {
    iron_handtrowel = { name = "Železni ročna lopatka", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni ročna lopatka za vrtnarje." },
    bronze_handtrowel = { name = "Bronast ročna lopatka", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast ročna lopatka za vrtnarje." },
    silver_handtrowel = { name = "Srebrn ročna lopatka", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn ročna lopatka za vrtnarje." },
    gilded_handtrowel = { name = "Pozlačen ročna lopatka", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen ročna lopatka za vrtnarje." },
    jewel_set_handtrowel = { name = "Draguljast ročna lopatka", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast ročna lopatka za vrtnarje." },
    royal_sovereign_handtrowel = { name = "Kraljevski suveren ročna lopatka", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren ročna lopatka z biseri za krono." },
}
local BUILDINGS = {
    handtrowel_workshop = { name = "Handtrowel delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    handtrowel_house = { name = "Handtrowel hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_handtrowel_atelier = { name = "Mojstrski handtrowel atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_handtrowel_palace = { name = "Suverena handtrowel palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
HandTrowelMaker.ironStock=16; HandTrowelMaker.bronzeStock=12; HandTrowelMaker.woodStock=12; HandTrowelMaker.leatherStock=8; HandTrowelMaker.silverStock=8; HandTrowelMaker.goldStock=6; HandTrowelMaker.jewelStock=4; HandTrowelMaker.pearlStock=4
HandTrowelMaker.productStock = {}; HandTrowelMaker.buildings = {}; HandTrowelMaker.maker = nil; HandTrowelMaker.activeMaking = {}; HandTrowelMaker.totalProducts = 0; HandTrowelMaker.dayTimer = 0
function HandTrowelMaker.init() HandTrowelMaker.ironStock=16; HandTrowelMaker.bronzeStock=12; HandTrowelMaker.woodStock=12; HandTrowelMaker.leatherStock=8; HandTrowelMaker.silverStock=8; HandTrowelMaker.goldStock=6; HandTrowelMaker.jewelStock=4; HandTrowelMaker.pearlStock=4; HandTrowelMaker.productStock={}; HandTrowelMaker.buildings={}; HandTrowelMaker.maker=nil; HandTrowelMaker.activeMaking={}; HandTrowelMaker.totalProducts=0; HandTrowelMaker.dayTimer=0; print("[HandTrowelMaker] Royal Hand Trowel Maker System initialized (6 products, 4 buildings)") end
function HandTrowelMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HandTrowelMaker.maker={name=n or ("Lopatar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lopatar najet: %s (spretnost: %d)",HandTrowelMaker.maker.name,s),"success") end; return true end
function HandTrowelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HandTrowelMaker.build(id) local ok,e=HandTrowelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HandTrowelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HandTrowelMaker.getQualityBonus() local b=0; for _,bd in ipairs(HandTrowelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HandTrowelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HandTrowelMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HandTrowelMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HandTrowelMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HandTrowelMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HandTrowelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HandTrowelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HandTrowelMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HandTrowelMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HandTrowelMaker.buildings==0 then return false,"Potrebna lopatna delavnica" end; if not HandTrowelMaker.maker then return false,"Potreben lopatar" end; return true end
function HandTrowelMaker.make(pt,qty) qty=qty or 1; local ok,e=HandTrowelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HandTrowelMaker.ironStock=HandTrowelMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HandTrowelMaker.bronzeStock=HandTrowelMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HandTrowelMaker.woodStock=HandTrowelMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HandTrowelMaker.leatherStock=HandTrowelMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HandTrowelMaker.silverStock=HandTrowelMaker.silverStock-d.silverCost*qty end; if d.goldCost then HandTrowelMaker.goldStock=HandTrowelMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HandTrowelMaker.jewelStock=HandTrowelMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HandTrowelMaker.pearlStock=HandTrowelMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HandTrowelMaker.maker then t=math.max(1,t-math.floor(HandTrowelMaker.maker.skill/13)) end; table.insert(HandTrowelMaker.activeMaking,{id="handtrowel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HandTrowelMaker.completeMaking(m) local q=1.0+(HandTrowelMaker.getQualityBonus()/100); if HandTrowelMaker.maker then q=q+(HandTrowelMaker.maker.skill/140) end; q=math.min(2.5,q); HandTrowelMaker.productStock[m.productType]=(HandTrowelMaker.productStock[m.productType] or 0)+m.quantity; HandTrowelMaker.totalProducts=HandTrowelMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HandTrowelMaker.maker then HandTrowelMaker.maker.itemsMade=HandTrowelMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HandTrowelMaker.maker.skill=math.min(100,HandTrowelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lopatka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"handtrowel.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function HandTrowelMaker.update(dt) if not _G.state then return end; HandTrowelMaker.dayTimer=HandTrowelMaker.dayTimer+dt; if HandTrowelMaker.dayTimer>=30 then HandTrowelMaker.dayTimer=0; for i=#HandTrowelMaker.activeMaking,1,-1 do local m=HandTrowelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HandTrowelMaker.completeMaking(m); table.remove(HandTrowelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HandTrowelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HandTrowelMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HandTrowelMaker.getStats() return {ironStock=HandTrowelMaker.ironStock,bronzeStock=HandTrowelMaker.bronzeStock,woodStock=HandTrowelMaker.woodStock,leatherStock=HandTrowelMaker.leatherStock,silverStock=HandTrowelMaker.silverStock,goldStock=HandTrowelMaker.goldStock,jewelStock=HandTrowelMaker.jewelStock,pearlStock=HandTrowelMaker.pearlStock,productStock=HandTrowelMaker.productStock,numBuildings=#HandTrowelMaker.buildings,hasMaker=HandTrowelMaker.maker~=nil,makerName=HandTrowelMaker.maker and HandTrowelMaker.maker.name or "—",makerSkill=HandTrowelMaker.maker and HandTrowelMaker.maker.skill or 0,activeMaking=#HandTrowelMaker.activeMaking,totalProducts=HandTrowelMaker.totalProducts} end
return HandTrowelMaker
